-- VibeTradez local development seed data
--
-- AUTO-GENERATED by generate-seed.py — do not hand-edit. Re-run that
-- script to refresh; the random seed is fixed so output is stable.
--
-- Realistic portfolio-manager data for the local dashboard: a year of
-- equity curve vs SPY, the last several sessions with stances + moves,
-- a full mock transcript per session day, and a few subscribers.

-- ── Schema (mirrors internal/store/store.go migrate()) ──────────────
CREATE TABLE IF NOT EXISTS subscribers (
    id SERIAL PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL DEFAULT '',
    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    unsubscribed_at TIMESTAMPTZ,
    auth_user_id BIGINT
);
CREATE TABLE IF NOT EXISTS transcripts (
    id SERIAL PRIMARY KEY,
    date TEXT NOT NULL,
    kind TEXT NOT NULL,
    model TEXT NOT NULL DEFAULT '',
    events JSONB NOT NULL,
    usage JSONB NOT NULL DEFAULT '{}',
    duration_ms BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (date, kind)
);
CREATE TABLE IF NOT EXISTS portfolio_decisions (
    id SERIAL PRIMARY KEY,
    uuid TEXT NOT NULL DEFAULT gen_random_uuid()::text,
    date TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT 'agent',
    action TEXT NOT NULL,
    asset_type TEXT NOT NULL DEFAULT '',
    symbol TEXT NOT NULL DEFAULT '',
    underlying TEXT NOT NULL DEFAULT '',
    contract_type TEXT NOT NULL DEFAULT '',
    strike DOUBLE PRECISION,
    expiration TEXT,
    quantity DOUBLE PRECISION NOT NULL DEFAULT 0,
    limit_price DOUBLE PRECISION NOT NULL DEFAULT 0,
    notional DOUBLE PRECISION NOT NULL DEFAULT 0,
    mode TEXT NOT NULL DEFAULT 'live',
    schwab_order_id TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT '',
    fill_price DOUBLE PRECISION,
    execution_id INTEGER NOT NULL DEFAULT 0,
    rationale TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS portfolio_sessions (
    date TEXT PRIMARY KEY,
    mode TEXT NOT NULL DEFAULT 'live',
    stance TEXT NOT NULL DEFAULT '',
    summary TEXT NOT NULL DEFAULT '',
    action_items TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS portfolio_equity_curve (
    date TEXT PRIMARY KEY,
    account_equity DOUBLE PRECISION NOT NULL DEFAULT 0,
    settled_cash DOUBLE PRECISION NOT NULL DEFAULT 0,
    unsettled_cash DOUBLE PRECISION NOT NULL DEFAULT 0,
    high_water_mark DOUBLE PRECISION NOT NULL DEFAULT 0,
    spy_close DOUBLE PRECISION NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS portfolio_positions (
    id SERIAL PRIMARY KEY,
    date TEXT NOT NULL,
    symbol TEXT NOT NULL,
    underlying TEXT NOT NULL DEFAULT '',
    asset_type TEXT NOT NULL DEFAULT '',
    contract_type TEXT NOT NULL DEFAULT '',
    strike DOUBLE PRECISION,
    expiration TEXT,
    quantity DOUBLE PRECISION NOT NULL DEFAULT 0,
    market_value DOUBLE PRECISION NOT NULL DEFAULT 0,
    cost_basis DOUBLE PRECISION NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

TRUNCATE subscribers, transcripts, portfolio_decisions, portfolio_sessions, portfolio_equity_curve, portfolio_positions;

